pub fn generate_state_expression(state_binding: &StateBinding, component_state: &ComponentState) -> String {
    match state_binding {
        StateBinding::Identifier { name } => {
            // Simple identifier: state={currentTime} -> currentTime
            name.clone()
        }
        StateBinding::MemberExpression { binding, .. } => {
            // Member expression: state={this.state.time} -> state.time (remove 'this')
            binding.clone()
        }
        StateBinding::ObjectExpression { .. } => {
            // Inline object: state={{ hours: h, minutes: m }}
            generate_inline_object(state_binding, component_state)
        }
        StateBinding::ComplexExpression { expression, .. } => {
            // Complex expression: evaluate using expression generator
            generate_csharp_expression(expression)
        }
    }
}

rust_types.StateBinding:
enum StateBinding {
    Identifier { name: String },
    MemberExpression { binding: String },
    ObjectExpression { properties: Vec<ObjectProperty> },
    ComplexExpression { expression: Expr },
}
